from __future__ import annotations

"""TrialForge verifier evaluation on Chalk (generated by build_eval_bundle.py — do not edit by hand).

Task:    tf_verify(rec_json, ctx_json, offline_json) -> verifier result JSON (same code as trialforge/verifier.py)
Scorers: verdict_correct  - 1.0 if the outcome matches the case kind (fault->REJECTED, valid->not REJECTED,
                            ambiguous->PASSED_WITH_WARNINGS)
         rejected_fault   - for injected faults only: 1.0 if rejected (catch rate)
         false_rejection  - for valid cases only: 1.0 if wrongly rejected
         valid-json       - built-in json_valid
         fault-explained  - optional LLM judge through the Chalk Model Gateway (--judge-model): does the
                            verifier's failure reason identify the injected fault?

Run (after `chalk login` and selecting an environment with Evaluations enabled):
    ../.venv/bin/python trialforge_chalk_eval.py --run [--judge-model <model from `chalk router model list`>]
"""
import json
import sys

import chalkcompute

# ----------------------------------------------------------------------------- inlined verifier
# <<VERIFIER_SOURCE>>


# ----------------------------------------------------------------------------- offline resolvers
def _normalize(s):
    import re as _re
    s = s.replace("’", "'").replace("‘", "'").replace("“", '"').replace("”", '"').replace("–", "-").replace("—", "-").replace("­", "")
    return _re.sub(r"\s+", " ", s).strip()


def _offline_resolvers(offline):
    fda = offline.get("fda_texts", {})
    reg = offline.get("registry", {})
    prot = offline.get("protocol_text")

    def fda_quote(g, q):
        if g not in fda:
            return {"ok": False, "reason": f"unknown guidance '{g}'"}
        return {"ok": True, "section": "", "fda_lines": "n/a (offline)"} if _normalize(q) in fda[g] else {"ok": False, "reason": "quoted text not found verbatim in the FDA PDF"}

    def nct_exists(n):
        return reg.get(n, {}).get("exists")

    def nct_threshold(n, analyte):
        return next((c for c in reg.get(n, {}).get("criteria", []) if c["analyte"] == analyte), None)

    def protocol_quote(_n, q):
        return None if prot is None else _normalize(q) in prot

    return {"fda_quote": fda_quote, "nct_exists": nct_exists, "nct_threshold": nct_threshold, "protocol_quote": protocol_quote}


# ----------------------------------------------------------------------------- Chalk functions
@chalkcompute.function
def tf_verify(rec_json: str, ctx_json: str, offline_json: str) -> str:
    out = verify(json.loads(rec_json), json.loads(ctx_json), _offline_resolvers(json.loads(offline_json)))
    return json.dumps(out)


@chalkcompute.function
def verdict_correct(kind: str, output: str) -> float:
    status = json.loads(output)["status"]
    if kind == "fault":
        return 1.0 if status == "REJECTED" else 0.0
    if kind == "valid":
        return 1.0 if status != "REJECTED" else 0.0
    return 1.0 if status == "PASSED_WITH_WARNINGS" else 0.0


@chalkcompute.function
def rejected_fault(kind: str, output: str) -> list[chalkcompute.EvaluationScorerResult]:
    """Catch rate on injected faults; emits no score for other rows."""
    if kind != "fault":
        return []
    return [chalkcompute.EvaluationScorerResult(score=1.0 if json.loads(output)["status"] == "REJECTED" else 0.0)]


@chalkcompute.function
def false_rejection(kind: str, output: str) -> list[chalkcompute.EvaluationScorerResult]:
    """Rate at which valid recommendations are rejected; emits no score for other rows."""
    if kind != "valid":
        return []
    return [chalkcompute.EvaluationScorerResult(score=1.0 if json.loads(output)["status"] == "REJECTED" else 0.0)]


valid_json = chalkcompute.scorers.json_valid(name="valid-json")


def _judge(model):
    from pydantic import BaseModel

    class FaultExplained(BaseModel):
        score: float  # 1.0 if the failed checks correctly identify the injected fault, else 0.0
        reason: str

    return chalkcompute.scorers.llm_judge(
        FaultExplained,
        model=model,
        name="fault-explained",
        inputs=("output", "fault_type", "description"),
        instructions=(
            "You grade a verifier for clinical-trial eligibility recommendations. 'output' is the verifier's JSON "
            "result; 'fault_type' and 'description' describe an error that was deliberately injected into the input "
            "(empty for non-fault cases). Score 1.0 if, for a fault case, the checks with result 'fail' identify that "
            "specific fault (not just any failure); for a non-fault case score 1.0 if the output does not invent a fault. "
            "Otherwise 0.0. Be strict."
        ),
    )


if __name__ == "__main__":
    import argparse
    from pathlib import Path

    ap = argparse.ArgumentParser()
    ap.add_argument("--run", action="store_true")
    ap.add_argument("--judge-model", default=None)
    args = ap.parse_args()
    rows = [json.loads(l) for l in (Path(__file__).parent / "eval_dataset.jsonl").read_text().splitlines()]
    if not args.run:
        # local dry run of the identical task + scorer logic (no Chalk calls)
        ok = 0
        for r in rows:
            out = verify(json.loads(r["rec_json"]), json.loads(r["ctx_json"]), _offline_resolvers(json.loads(r["offline_json"])))
            s = out["status"]
            good = (s == "REJECTED") if r["kind"] == "fault" else (s != "REJECTED") if r["kind"] == "valid" else (s == "PASSED_WITH_WARNINGS")
            ok += good
            if not good:
                print("MISMATCH", r["case_id"], r["kind"], s)
        print(f"local dry run: {ok}/{len(rows)} verdicts correct")
        sys.exit(0)

    scorers = [verdict_correct, rejected_fault, false_rejection, valid_json]
    if args.judge_model:
        scorers.append(_judge(args.judge_model))
    dataset = chalkcompute.DatasetClient().upload("trialforge-verifier-cases", rows)
    evaluation = chalkcompute.Evaluation.create("trialforge-verifier", dataset=dataset, task=tf_verify, scorers=scorers)
    run = evaluation.run(metadata={"suite": "verifier", "n_cases": len(rows)}).wait()
    print("status:", run.status)
    ids = {k: str(getattr(x, a, "")) for k, x, a in (("evaluation_id", evaluation, "id"), ("run_id", run, "id"), ("result_dataset", run, "result_dataset"))}
    print("ids:", ids)
    table = chalkcompute.DatasetClient().read(run.result_dataset)
    cols = table.column_names
    print("columns:", cols)
    recs = table.to_pylist()
    out_rows = []
    for r in recs:
        out = r.get("output")
        status = None
        try:
            status = json.loads(out)["status"] if out else None
        except Exception:
            status = "unparseable"
        out_rows.append({"case_id": r.get("case_id"), "kind": r.get("kind"), "expected": r.get("expected"), "remote_status": status,
                         "output_error": r.get("output_error"),
                         **{c: r.get(c) for c in cols if c.endswith("_value") or c.endswith("_error") or (c.startswith("scorer_") and not c.endswith("_error"))}})
    for o in out_rows[:3]:
        print("sample:", {k: (str(v)[:160] if v is not None else None) for k, v in o.items()})
    def agree(o):
        s = o["remote_status"]
        return (s == "REJECTED") if o["kind"] == "fault" else (s not in (None, "unparseable", "REJECTED")) if o["kind"] == "valid" else (s == "PASSED_WITH_WARNINGS")
    summary = {"status": str(run.status), "rows": len(recs), **ids,
               "task_errors": sum(1 for o in out_rows if o["output_error"]),
               "verdicts_matching_expectation": sum(1 for o in out_rows if agree(o)),
               "fault_rejected": sum(1 for o in out_rows if o["kind"] == "fault" and o["remote_status"] == "REJECTED"),
               "n_fault": sum(1 for o in out_rows if o["kind"] == "fault"),
               "valid_rejected": sum(1 for o in out_rows if o["kind"] == "valid" and o["remote_status"] == "REJECTED"),
               "n_valid": sum(1 for o in out_rows if o["kind"] == "valid"),
               "ambiguous_flagged": sum(1 for o in out_rows if o["kind"] == "ambiguous" and o["remote_status"] == "PASSED_WITH_WARNINGS"),
               "n_ambiguous": sum(1 for o in out_rows if o["kind"] == "ambiguous")}
    def num(v):
        try:
            return float(v)
        except (TypeError, ValueError):
            return None
    # map scorer-id columns back to scorer names (same order as passed to Evaluation.create)
    scorer_cols = [c for c in cols if c.startswith("scorer_") and not c.endswith("_error")]
    names = {c: n for c, n in zip(scorer_cols, ["verdict_correct", "rejected_fault", "false_rejection"])}
    summary["scorer_column_names"] = names
    for c in scorer_cols + [c for c in cols if c.endswith("_value")]:
        vals = [x for x in (num(r.get(c)) for r in recs) if x is not None]
        summary[names.get(c, c) + "_mean"] = (sum(vals) / len(vals)) if vals else None
        summary[names.get(c, c) + "_n"] = len(vals)
    summary["note"] = "scorer-id -> name mapping assumes Chalk preserves the order scorers were passed in; verified by comparing each scorer's n with the number of fault/valid rows."
    print(json.dumps(summary, indent=1))
    root = Path(__file__).parent.parent / "data"
    (root / "chalk_eval_run.json").write_text(json.dumps({**summary, "evaluation": "trialforge-verifier", "ran_at": __import__("time").strftime("%Y-%m-%d %H:%M:%S")}, indent=1))
    (root / "chalk_eval_rows.json").write_text(json.dumps(out_rows, indent=1, default=str))
